	const PASTE_INLINE_MAP = { STRONG: 'strong', B: 'strong', EM: 'em', I: 'em', S: 's', STRIKE: 's', DEL: 's', CODE: 'code', SAMP: 'code', TT: 'code', KBD: 'kbd', SUB: 'sub', SUP: 'sup' };
